from collections import deque


def shortest_path(grid):
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return -1
    queue = deque([(0, 0, 0)])                 # row, column, steps taken to get here
    seen = {(0, 0)}
    while queue:
        row, col, steps = queue.popleft()
        if (row, col) == (rows - 1, cols - 1):
            return steps                       # breadth-first: the first arrival is the shortest
        for r, c in ((row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)):
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == 0 and (r, c) not in seen:
                seen.add((r, c))               # mark it now, so it is never queued twice
                queue.append((r, c, steps + 1))
    return -1
